        emon.Port.Cells out = emon.Port.newCells();
        emon.Testport.assertEq(Pdffilter.pfA85(emon.Testport.textBlob("xx87cURDZ~>xx"), 2, 11, out), 0, "a85 status");
        emon.Testport.assertCellsHex(out, "48656c6c6f", "a85 range");
