    public static void testCryptIsTheIdentityAndImageFiltersAreDeclined() {
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Testport.assertEq(Pdffilter.pfRun(Pdffilter.pfFCrypt(), emon.Testport.hexBlob("0102"), 0, 2, out, st, 1), 0, "crypt");
        emon.Testport.assertCellsHex(out, "0102", "unchanged");
        emon.Testport.assertEq(Pdffilter.pfRun(Pdffilter.pfFDct(), emon.Testport.hexBlob("ffd8"), 0, 2, out, st, 1), Pdffilter.pfImageFilter(), "dct declined");
        emon.Testport.assertEq(emon.Port.cellsLen(out), 2, "out untouched by an image filter");
        emon.Testport.assertEq(Pdffilter.pfRun(99, emon.Testport.hexBlob("00"), 0, 1, out, st, 1), Pdffilter.pfUnsupported(), "unknown");
    }
